import {deckStats,zones,zoneLabels} from './deck-model.mjs?v=2';
import {CardSearch} from './card-search.mjs';
export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeHTML;
export function descriptionHTML(text){
 let out='',list=false;
 for(const line of String(text||'').split('\n')){
  if(/^[-*] /.test(line)){if(!list){out+='<ul>';list=true;}out+='<li>'+esc(line.slice(2))+'</li>';continue;}
  if(list){out+='</ul>';list=false;}
  const h=/^(#{1,3})\s+(.+)$/.exec(line);
  if(h)out+=`<h${h[1].length+1}>${esc(h[2])}</h${h[1].length+1}>`;
  else if(line.trim())out+='<p>'+esc(line)+'</p>';
 }
 return out+(list?'</ul>':'');
}
export function rarityLabel(card,lang){return CardSearch.label(card?.text?.rarity|| (lang==='en'?'Unknown rarity':'Seltenheit unbekannt'),lang);}
export function mountPresentation(root,deck,index,lang){
 const t=(d,e)=>lang==='en'?e:d;let view='text',group='type',sort='name';
 const stats=deckStats(deck,index),cover=index.flatMap(g=>g.variants).find(c=>c.id===deck.coverPrintingId);
 root.innerHTML=`${cover?`<div class="deck-cover"><img src="${esc(cover.image)}" alt="${esc(cover.name)}"><div><p>${esc(deck.summary||'')}</p></div></div>`:deck.summary?`<p class="intro">${esc(deck.summary)}</p>`:''}<div class="deck-view-controls"><label>${t('Ansicht','View')}<select id="deck-view"><option value="text">${t('Textliste','Text list')}</option><option value="images">${t('Kartenbilder','Card images')}</option></select></label><label>${t('Gruppierung','Group by')}<select id="deck-group"><option value="type">${t('Kartentyp','Card type')}</option><option value="rarity">${t('Seltenheit','Rarity')}</option><option value="color">${t('Farbe','Color')}</option><option value="none">${t('Nur Deckbereiche','Deck zones only')}</option></select></label><label>${t('Sortierung','Sort by')}<select id="deck-sort"><option value="name">Name</option><option value="asp">ASP</option><option value="quantity">${t('Anzahl','Quantity')}</option></select></label></div><div id="presented-cards"></div><section class="deck-statistics"><h2>${t('Statistiken','Statistics')}</h2><p>${stats.total} ${t('Karten ohne Merkliste','cards excluding considering')}</p><div class="statistics-grid"><section><h3>${t('Deckbereiche','Deck zones')}</h3><dl>${zones.map(z=>`<div><dt>${zoneLabels[z][lang==='en'?1:0]}</dt><dd>${stats.counts[z]}</dd></div>`).join('')}</dl></section><section><h3>${t('ASP-Kurve · Spell-Deck','ASP curve · Spell deck')}</h3><div class="deck-curve">${Object.entries(stats.curve).sort((a,b)=>Number(a[0])-Number(b[0])).map(([n,q])=>`<div><span>{${esc(n)}}</span><meter min="0" max="${Math.max(1,...Object.values(stats.curve))}" value="${q}">${q}</meter><b>${q}</b></div>`).join('')||'—'}</div><p class="muted">${stats.unknown} ${t('ohne erfasste ASP-Kosten','without recorded ASP cost')}</p></section>${[['colors',t('Farben','Colors')],['types',t('Kartentypen','Card types')],['rarities',t('Seltenheiten','Rarities')]].map(([k,label])=>`<section><h3>${label}</h3><dl>${Object.entries(stats[k]).sort((a,b)=>b[1]-a[1]).map(([name,q])=>`<div><dt>${esc(CardSearch.label(name,lang))}</dt><dd>${q}</dd></div>`).join('')||'—'}</dl></section>`).join('')}</div><p class="muted">${t('Mehrfarbige Karten und Karten mit mehreren Typen zählen in jeder passenden Kategorie.','Multicolor and multi-type cards count in each matching category.')}</p></section><section class="deck-check"><h2>${t('Deckbauprüfung','Deck checks')}</h2><p>${t('Kopienlimits werden über alle Versionen und Deckbereiche zusammengezählt, ohne Merkliste. Formatgrenzen, Herrscherbeschränkungen und Verbotslisten sind noch nicht vollständig geprüft.','Copy limits combine all printings and deck zones, excluding considering. Format sizes, Sovereign restrictions and banned lists are not fully checked yet.')}</p>${stats.issues.length?`<ul>${stats.issues.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:`<p>${t('Keine Überschreitung der bekannten Kopienlimits.','No known copy limits exceeded.')}</p>`}<p>${stats.unknownRarity} ${t('Kartennamen mit unbekannter oder widersprüchlicher Seltenheit.','card names with unknown or conflicting rarity.')}</p><a href="#/${lang}/rules/2.4">${t('Deckbauregeln','Deck building rules')}</a></section>${deck.description?`<details class="deck-description"><summary>${t('Ausführliche Deckbeschreibung','Full deck description')}</summary>${descriptionHTML(deck.description)}</details>`:''}`;
 const $=s=>root.querySelector(s);
 for(const [id,change] of [['deck-view',v=>view=v],['deck-group',v=>group=v],['deck-sort',v=>sort=v]])$('#'+id).onchange=e=>{change(e.target.value);draw();};
 function draw(){
  $('#presented-cards').innerHTML=zones.map(z=>{
   const entries=deck.entries.filter(e=>e.zone===z).map(e=>({...e,card:index.find(g=>g.id===e.cardId)?.variants.find(c=>c.id===e.printingId)}));if(!entries.length)return '';
   entries.sort((a,b)=>sort==='asp'?(a.card.text?.stats?.asp??Infinity)-(b.card.text?.stats?.asp??Infinity)||a.card.name.localeCompare(b.card.name):sort==='quantity'?b.quantity-a.quantity||a.card.name.localeCompare(b.card.name):a.card.name.localeCompare(b.card.name));
   const groups=new Map();for(const e of entries){const d=e.card.text||{},key=group==='type'?(d.types||[]).map(x=>CardSearch.label(x,lang)).join(' / '):group==='rarity'?rarityLabel(e.card,lang):group==='color'?(d.colors||[]).map(x=>CardSearch.label(x,lang)).join(' / '):'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);}
   return `<section class="presented-zone"><h2>${zoneLabels[z][lang==='en'?1:0]} <small>${entries.reduce((n,e)=>n+e.quantity,0)}</small></h2><div class="presentation-groups ${view==='images'?'image-groups':''}">${[...groups].map(([key,items])=>`<section>${key?`<h3>${esc(key)}</h3>`:''}<div class="${view==='images'?'presentation-images':'presentation-text'}">${items.map(e=>`<a class="presentation-card ${view==='text'?'deck-card-name':''}" href="#/${lang}/card/${e.card.id}">${view==='images'?`<img src="${esc(e.card.image)}" alt="${esc(e.card.name)}" loading="lazy">`:''}<span class="presentation-quantity">${e.quantity}×</span><span>${esc(e.card.name)}</span><small>${esc(rarityLabel(e.card,lang))}</small>${view==='text'?`<img class="deck-hover" src="${esc(e.card.image)}" alt="" loading="lazy">`:''}</a>`).join('')}</div></section>`).join('')}</div></section>`;
  }).join('')||`<p>${t('Dieses Deck enthält noch keine Karten. Wähle „Bearbeiten“, um loszulegen.','This deck has no cards yet. Choose “Edit” to get started.')}</p>`;
 }
 draw();
}
